#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;

    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle for mackerels
    int x_min1 = INT_MAX;
    int x_max1 = INT_MIN;
    int y_min1 = INT_MAX;
    int y_max1 = INT_MIN;

    for (const auto& p : mackerels) {
        x_min1 = min(x_min1, p.x);
        x_max1 = max(x_max1, p.x);
        y_min1 = min(y_min1, p.y);
        y_max1 = max(y_max1, p.y);
    }

    // Helper functions to count mackerels and sardines in a rectangle
    auto count_mackerels = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        for (const auto& p : mackerels) {
            if (p.x >= x_min && p.x <= x_max && p.y >= y_min && p.y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    auto count_sardines = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        for (const auto& p : sardines) {
            if (p.x >= x_min && p.x <= x_max && p.y >= y_min && p.y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    // Initial score calculation
    int b_initial = count_sardines(x_min1, x_max1, y_min1, y_max1);
    int max_val = (N - b_initial + 1);
    if (max_val < 0) max_val = 0;
    int best_x_min = x_min1;
    int best_x_max = x_max1;
    int best_y_min = y_min1;
    int best_y_max = y_max1;

    // Try adjusting for each sardine
    for (const auto& s : sardines) {
        int xs = s.x;
        int ys = s.y;

        // Check if s is inside the initial rectangle
        bool inside = (xs >= x_min1 && xs <= x_max1 && ys >= y_min1 && ys <= y_max1);

        if (inside) {
            // Try adjusting x_max
            int new_xmax = xs - 1;
            if (new_xmax >= x_min1) {
                int a = count_mackerels(x_min1, new_xmax, y_min1, y_max1);
                int b = count_sardines(x_min1, new_xmax, y_min1, y_max1);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = x_min1;
                    best_x_max = new_xmax;
                    best_y_min = y_min1;
                    best_y_max = y_max1;
                }
            }

            // Try adjusting x_min
            int new_xmin = xs + 1;
            if (new_xmin <= x_max1) {
                int a = count_mackerels(new_xmin, x_max1, y_min1, y_max1);
                int b = count_sardines(new_xmin, x_max1, y_min1, y_max1);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = new_xmin;
                    best_x_max = x_max1;
                    best_y_min = y_min1;
                    best_y_max = y_max1;
                }
            }

            // Try adjusting y_max
            int new_ymax = ys - 1;
            if (new_ymax >= y_min1) {
                int a = count_mackerels(x_min1, x_max1, y_min1, new_ymax);
                int b = count_sardines(x_min1, x_max1, y_min1, new_ymax);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = x_min1;
                    best_x_max = x_max1;
                    best_y_min = y_min1;
                    best_y_max = new_ymax;
                }
            }

            // Try adjusting y_min
            int new_ymin = ys + 1;
            if (new_ymin <= y_max1) {
                int a = count_mackerels(x_min1, x_max1, new_ymin, y_max1);
                int b = count_sardines(x_min1, x_max1, new_ymin, y_max1);
                int val = a - b;
                if (val > max_val) {
                    max_val = val;
                    best_x_min = x_min1;
                    best_x_max = x_max1;
                    best_y_min = new_ymin;
                    best_y_max = y_max1;
                }
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_x_min << " " << best_y_min << endl;
    cout << best_x_max << " " << best_y_min << endl;
    cout << best_x_max << " " << best_y_max << endl;
    cout << best_x_min << " " << best_y_max << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle for mackerels
    int min_x_m = INT_MAX;
    int max_x_m = INT_MIN;
    int min_y_m = INT_MAX;
    int max_y_m = INT_MIN;
    for (auto [x, y] : mackerels) {
        min_x_m = min(min_x_m, x);
        max_x_m = max(max_x_m, x);
        min_y_m = min(min_y_m, y);
        max_y_m = max(max_y_m, y);
    }

    // Count initial sardines in the rectangle
    int initial_sardines = 0;
    for (auto [x, y] : sardines) {
        if (x >= min_x_m && x <= max_x_m && y >= min_y_m && y <= max_y_m) {
            initial_sardines++;
        }
    }

    // Compute initial score and best_rect
    int best_score = 0;
    int best_x_min = min_x_m;
    int best_x_max = max_x_m;
    int best_y_min = min_y_m;
    int best_y_max = max_y_m;
    int m_initial = N;
    int score_initial = max(0, m_initial - initial_sardines + 1);
    best_score = score_initial;

    // Collect sardines inside initial rectangle
    vector<pair<int, int>> sardines_in_initial;
    for (auto [x, y] : sardines) {
        if (x >= min_x_m && x <= max_x_m && y >= min_y_m && y <= max_y_m) {
            sardines_in_initial.push_back({x, y});
        }
    }

    // For each sardine in sardines_in_initial, generate adjusted rectangles
    for (auto [x_s, y_s] : sardines_in_initial) {
        // Adjust x to the left of x_s
        int new_x_min = min_x_m;
        int new_x_max = x_s - 1;
        if (new_x_max >= new_x_min) {
            int m = 0;
            int s = 0;
            for (auto [x, y] : mackerels) {
                if (x >= new_x_min && x <= new_x_max && y >= min_y_m && y <= max_y_m) {
                    m++;
                }
            }
            for (auto [x, y] : sardines) {
                if (x >= new_x_min && x <= new_x_max && y >= min_y_m && y <= max_y_m) {
                    s++;
                }
            }
            int current_score = max(0, m - s + 1);
            if (current_score > best_score) {
                best_score = current_score;
                best_x_min = new_x_min;
                best_x_max = new_x_max;
                best_y_min = min_y_m;
                best_y_max = max_y_m;
            }
        }
        // Adjust x to the right of x_s
        int new_x_min_2 = x_s + 1;
        int new_x_max_2 = max_x_m;
        if (new_x_min_2 <= new_x_max_2) {
            int m = 0;
            int s = 0;
            for (auto [x, y] : mackerels) {
                if (x >= new_x_min_2 && x <= new_x_max_2 && y >= min_y_m && y <= max_y_m) {
                    m++;
                }
            }
            for (auto [x, y] : sardines) {
                if (x >= new_x_min_2 && x <= new_x_max_2 && y >= min_y_m && y <= max_y_m) {
                    s++;
                }
