        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute bounding box for mackerels
    int x_l = INT_MAX, x_r = INT_MIN, y_b = INT_MAX, y_t = INT_MIN;
    for (auto p : mackerels) {
        x_l = min(x_l, p.x);
        x_r = max(x_r, p.x);
        y_b = min(y_b, p.y);
        y_t = max(y_t, p.y);
    }

    // Helper functions to count points in a rectangle
    auto count_mackerels = [&](int x1, int x2, int y1, int y2) {
        int cnt = 0;
        for (auto p : mackerels) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                ++cnt;
            }
        }
        return cnt;
    };

    auto count_sardines = [&](int x1, int x2, int y1, int y2) {
        int cnt = 0;
        for (auto p : sardines) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                ++cnt;
            }
        }
        return cnt;
    };

    // Initial rectangle
    int current_x1 = x_l;
    int current_x2 = x_r;
    int current_y1 = y_b;
    int current_y2 = y_t;
