            int new_y1_bottom = best_y1;
            int new_y2_bottom = s_y - 1;
            if (new_y1_bottom < new_y2_bottom) {
                int new_a = count_mackerels(best_x1, new_y1_bottom, best_x2, new_y2_bottom);
                int new_b = count_sardines(best_x1, new_y1_bottom, best_x2, new_y2_bottom);
