                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = new_xmin;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = curr_y_max;
                }
            }

            // Option 2: move right edge to xs - 1
            int new_xmax = xs - 1;
            if (new_xmax >= curr_x_min) {
                int a = count_mackerels(curr_x_min, new_xmax, curr_y_min, curr_y_max);
                int b = count_sardines(curr_x_min, new_xmax, curr_y_min, curr_y_max);
