                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = new_xmax;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = curr_y_max;
                }
            }

            // Option 3: move bottom edge to ys + 1
            int new_ymin = ys + 1;
            if (new_ymin <= curr_y_max) {
                int a = count_mackerels(curr_x_min, curr_x_max, new_ymin, curr_y_max);
                int b = count_sardines(curr_x_min, curr_x_max, new_ymin, curr_y_max);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = new_ymin;
                    best_new_y_max = curr_y_max;
                }
            }

            // Option 4: move top edge to ys - 1
            int new_ymax = ys - 1;
            if (new_ymax >= curr_y_min) {
                int a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, new_ymax);
                int b = count_sardines(curr_x_min, curr_x_max, curr_y_min, new_ymax);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = new_ymax;
                }
            }
        }

        // Check if any improvement
        if (best_new_val > curr_val) {
            curr_val = best_new_val;
            curr_a = best_new_a;
            curr_b = best_new_b;
            curr_x_min = best_new_x_min;
            curr_x_max = best_new_x_max;
            curr_y_min = best_new_y_min;
            curr_y_max = best_new_y_max;
            improved = true;
        }
