        // Check if s is inside initial R
        if (sx >= x_min_m && sx <= x_max_m && sy >= y_min_m && sy <= y_max_m) {
            // Generate four modified rectangles
            // 1. adjust x_max to sx - 1
            int new_xmin1 = x_min_m;
            int new_xmax1 = sx - 1;
            if (new_xmax1 >= new_xmin1) {
                Rect r;
                r.xmin = new_xmin1;
                r.ymin = y_min_m;
                r.xmax = new_xmax1;
                r.ymax = y_max_m;
                candidates.push_back(r);
            }
            // 2. adjust x_min to sx + 1
            int new_xmin2 = sx + 1;
            int new_xmax2 = x_max_m;
            if (new_xmax2 >= new_xmin2) {
                Rect r;
                r.xmin = new_xmin2;
                r.ymin = y_min_m;
                r.xmax = new_xmax2;
