void precompute_mackerels(vector<pair<int, int>>& mackerels) {
    sort(mackerels.begin(), mackerels.end(), [](pair<int, int> a, pair<int, int> b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });
    xs_m.clear();
    ys_m.clear();
    for (auto& p : mackerels) {
        xs_m.push_back(p.first);
        ys_m.push_back(p.second);
    }
}

void precompute_sardines(vector<pair<int, int>>& sardines) {
    sort(sardines.begin(), sardines.end(), [](pair<int, int> a, pair<int, int> b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });
    xs_s.clear();
    ys_s.clear();
    for (auto& p : sardines) {
        xs_s.push_back(p.first);
        ys_s.push_back(p.second);
    }
}

