    int right = upper_bound(xs_m.begin(), xs_m.end(), x2) - xs_m.begin();
    int cnt = 0;
    for (int i = left; i < right; ++i) {
        if (ys_m[i] >= y1 && ys_m[i] <= y2) {
            cnt++;
        }
    }
    return cnt;
}

int count_sardines(int x1, int x2, int y1, int y2) {
