struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;

    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle for mackerels
    int x_min1 = INT_MAX;
    int x_max1 = INT_MIN;
    int y_min1 = INT_MAX;
    int y_max1 = INT_MIN;

    for (const auto& p : mackerels) {
        x_min1 = min(x_min1, p.x);
        x_max1 = max(x_max1, p.x);
        y_min1 = min(y_min1, p.y);
        y_max1 = max(y_max1, p.y);
    }

    // Helper functions to count mackerels and sardines in a rectangle
    auto count_mackerels = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        for (const auto& p : mackerels) {
            if (p.x >= x_min && p.x <= x_max && p.y >= y_min && p.y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    auto count_sardines = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        for (const auto& p : sardines) {
            if (p.x >= x_min && p.x <= x_max && p.y >= y_min && p.y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    int curr_x_min = x_min1;
    int curr_x_max = x_max1;
    int curr_y_min = y_min1;
    int curr_y_max = y_max1;
    int curr_a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
    int curr_b = count_sardines(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
    int curr_val = max(0, curr_a - curr_b + 1);

    bool improved = true;
    while (improved) {
        improved = false;
        vector<Point> current_sardines;
        for (const auto& s : sardines) {
            if (s.x >= curr_x_min && s.x <= curr_x_max && s.y >= curr_y_min && s.y <= curr_y_max) {
                current_sardines.push_back(s);
            }
        }

        if (current_sardines.empty()) {
            break;
        }

        int best_new_val = curr_val;
        int best_new_a = curr_a;
        int best_new_b = curr_b;
