using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Sort mackerels and sardines by x, then y
    sort(mackerels.begin(), mackerels.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });
    sort(sardines.begin(), sardines.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.first < b.first || (a.first == b.first && a.second < b.second);
    });

    // Function to count mackerels in [x1, x2] x [y1, y2]
    auto count_mackerels = [&](int x1, int y1, int x2, int y2) {
        int cnt = 0;
        auto left = lower_bound(mackerels.begin(), mackerels.end(), make_pair(x1, 0),
                                [](const pair<int, int>& a, const pair<int, int>& b) {
                                    return a.first < b.first;
                                });
        auto right = upper_bound(mackerels.begin(), mackerels.end(), make_pair(x2, INT_MAX),
                                 [](const pair<int, int>& a, const pair<int, int>& b) {
                                     return a.first < b.first;
                                 });
        for (auto it = left; it != right; ++it) {
            if (it->second >= y1 && it->second <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    // Function to count sardines in [x1, x2] x [y1, y2]
    auto count_sardines = [&](int x1, int y1, int x2, int y2) {
        int cnt = 0;
        auto left = lower_bound(sardines.begin(), sardines.end(), make_pair(x1, 0),
                                [](const pair<int, int>& a, const pair<int, int>& b) {
                                    return a.first < b.first;
                                });
        auto right = upper_bound(sardines.begin(), sardines.end(), make_pair(x2, INT_MAX),
                                 [](const pair<int, int>& a, const pair<int, int>& b) {
                                     return a.first < b.first;
                                 });
        for (auto it = left; it != right; ++it) {
            if (it->second >= y1 && it->second <= y2) {
                cnt++;
            }
        }
        return cnt;
    };

    // Initialize with bounding box of mackerels
    int min_x = INT_MAX, max_x = INT_MIN, min_y = INT_MAX, max_y = INT_MIN;
    for (auto [x, y] : mackerels) {
        min_x = min(min_x, x);
        max_x = max(max_x, x);
        min_y = min(min_y, y);
        max_y = max(max_y, y);
    }

    int best_x1 = min_x, best_x2 = max_x, best_y1 = min_y, best_y2 = max_y;
    int best_a = count_mackerels(best_x1, best_y1, best_x2, best_y2);
    int best_b = count_sardines(best_x1, best_y1, best_x2, best_y2);

    bool improved;
    do {
        improved = false;
        // Find all sardines inside current rectangle
        vector<pair<int, int>> sardines_in_rect;
        for (auto [x, y] : sardines) {
            if (x >= best_x1 && x <= best_x2 && y >= best_y1 && y <= best_y2) {
                sardines_in_rect.push_back({x, y});
            }
        }

        if (sardines_in_rect.empty()) {
            break;
        }

        int best_gain = -1;
        int new_x1 = best_x1, new_x2 = best_x2, new_y1 = best_y1, new_y2 = best_y2;
        int gain = 0;

        for (auto s : sardines_in_rect) {
            int s_x = s.first;
            int s_y = s.second;

            // Try adjusting x1 (move right to exclude s_x)
            int temp_x1 = s_x + 1;
            if (temp_x1 <= best_x2) {
                int a = count_mackerels(temp_x1, best_y1, best_x2, best_y2);
                int b = count_sardines(temp_x1, best_y1, best_x2, best_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = temp_x1;
                    new_x2 = best_x2;
                    new_y1 = best_y1;
                    new_y2 = best_y2;
                }
            }

            // Try adjusting x2 (move left to exclude s_x)
            int temp_x2 = s_x - 1;
            if (temp_x2 >= best_x1) {
                int a = count_mackerels(best_x1, best_y1, temp_x2, best_y2);
                int b = count_sardines(best_x1, best_y1, temp_x2, best_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = best_x1;
                    new_x2 = temp_x2;
                    new_y1 = best_y1;
                    new_y2 = best_y2;
                }
            }

            // Try adjusting y1 (move up to exclude s_y)
            int temp_y1 = s_y + 1;
            if (temp_y1 <= best_y2) {
                int a = count_mackerels(best_x1, temp_y1, best_x2, best_y2);
                int b = count_sardines(best_x1, temp_y1, best_x2, best_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = best_x1;
                    new_x2 = best_x2;
                    new_y1 = temp_y1;
                    new_y2 = best_y2;
                }
            }

            // Try adjusting y2 (move down to exclude s_y)
            int temp_y2 = s_y - 1;
            if (temp_y2 >= best_y1) {
                int a = count_mackerels(best_x1, best_y1, best_x2, temp_y2);
                int b = count_sardines(best_x1, best_y1, best_x2, temp_y2);
                int delta = (a - b) - (best_a - best_b);
                if (delta > best_gain) {
                    best_gain = delta;
                    new_x1 = best_x1;
                    new_x2 = best_x2;
                    new_y1 = best_y1;
                    new_y2 = temp_y2;
                }
            }
        }

        if (best_gain > 0) {
            best_a = count_mackerels(new_x1, new_y1, new_x2, new_y2);
            best_b = count_sardines(new_x1, new_y1, new_x2, new_y2);
            best_x1 = new_x1;
            best_x2 = new_x2;
            best_y1 = new_y1;
            best_y2 = new_y2;
            improved = true;
        }
    } while (improved);

    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y2 << endl;
    cout << best_x1 << " " << best_y2 << endl;

    return 0;
}

