#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <climits>
#include <utility>
#include <functional>
using namespace std;

struct Point {
    int x, y;
};

// Function to count the number of points in [x_min, x_max] x [y_min, y_max]
int count_points(const vector<int>& unique_x, const vector<vector<int>>& y_list, int x_min, int x_max, int y_min, int y_max) {
    int total = 0;
    // Binary search to find the range of x in unique_x that fall within [x_min, x_max]
    auto left = lower_bound(unique_x.begin(), unique_x.end(), x_min);
    auto right = upper_bound(unique_x.begin(), unique_x.end(), x_max);
    int left_idx = left - unique_x.begin();
    int right_idx = right - unique_x.begin();

    for (int i = left_idx; i < right_idx; ++i) {
        // For x = unique_x[i], count y's within [y_min, y_max]
        const vector<int>& ys = y_list[i];
        auto lower = lower_bound(ys.begin(), ys.end(), y_min);
        auto upper = upper_bound(ys.begin(), ys.end(), y_max);
        total += (upper - lower);
    }
    return total;
}

int main() {
    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;

    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Preprocess mackerels
    vector<Point> sorted_mackerels = mackerels;
    sort(sorted_mackerels.begin(), sorted_mackerels.end(), [](const Point &a, const Point &b) {
        return a.x != b.x ? a.x < b.x : a.y < b.y;
    });

    vector<int> unique_x_m;
    vector<vector<int>> y_list_m;
    int last_x = -1;
    for (const auto &p : sorted_mackerels) {
        if (p.x != last_x) {
            unique_x_m.push_back(p.x);
            y_list_m.push_back({});
            last_x = p.x;
        }
        y_list_m.back().push_back(p.y);
    }

    // Preprocess sardines
    vector<Point> sorted_sardines = sardines;
    sort(sorted_sardines.begin(), sorted_sardines.end(), [](const Point &a, const Point &b) {
        return a.x != b.x ? a.x < b.x : a.y < b.y;
    });

    vector<int> unique_x_s;
    vector<vector<int>> y_list_s;
    int last_sx = -1;
    for (const auto &p : sorted_sardines) {
        if (p.x != last_sx) {
            unique_x_s.push_back(p.x);
            y_list_s.push_back({});
            last_sx = p.x;
        }
        y_list_s.back().push_back(p.y);
    }

    // Initial rectangle: min/max x and y of mackerels
    int x_min1 = INT_MAX, x_max1 = INT_MIN, y_min1 = INT_MAX, y_max1 = INT_MIN;
    for (auto p : mackerels) {
        x_min1 = min(x_min1, p.x);
        x_max1 = max(x_max1, p.x);
        y_min1 = min(y_min1, p.y);
        y_max1 = max(y_max1, p.y);
    }

    auto count_mackerels = [&](int x_min, int x_max, int y_min, int y_max) {
        return count_points(unique_x_m, y_list_m, x_min, x_max, y_min, y_max);
    };

    auto count_sardines = [&](int x_min, int x_max, int y_min, int y_max) {
        return count_points(unique_x_s, y_list_s, x_min, x_max, y_min, y_max);
    };

    int curr_x_min = x_min1, curr_x_max = x_max1;
    int curr_y_min = y_min1, curr_y_max = y_max1;
    int curr_a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
    int curr_b = count_sardines(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
    int curr_val = max(0, curr_a - curr_b + 1);

    bool improved = true;
    while (improved) {
        improved = false;
        // Collect sardines currently inside the rectangle
        vector<Point> current_sardines_inside;
        for (const auto &s : sardines) {
            if (s.x >= curr_x_min && s.x <= curr_x_max && s.y >= curr_y_min && s.y <= curr_y_max) {
                current_sardines_inside.push_back(s);
            }
        }

        if (current_sardines_inside.empty()) {
            break;
        }

        int best_new_val = curr_val;
        int best_new_a = curr_a;
        int best_new_b = curr_b;
        int best_new_x_min = curr_x_min, best_new_x_max = curr_x_max;
        int best_new_y_min = curr_y_min, best_new_y_max = curr_y_max;

        for (const auto &s : current_sardines_inside) {
            int xs = s.x, ys = s.y;

            // Try moving left edge to exclude s
            int new_xmin = xs + 1;
            if (new_xmin <= curr_x_max) {
                int a = count_mackerels(new_xmin, curr_x_max, curr_y_min, curr_y_max);
                int b = count_sardines(new_xmin, curr_x_max, curr_y_min, curr_y_max);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = new_xmin;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = curr_y_max;
                    improved = true;
                }
            }

            // Try moving right edge to exclude s
            int new_xmax = xs - 1;
            if (new_xmax >= curr_x_min) {
                int a = count_mackerels(curr_x_min, new_xmax, curr_y_min, curr_y_max);
                int b = count_sardines(curr_x_min, new_xmax, curr_y_min, curr_y_max);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = new_xmax;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = curr_y_max;
                    improved = true;
                }
            }

            // Try moving bottom edge to exclude s
            int new_ymin = ys + 1;
            if (new_ymin <= curr_y_max) {
                int a = count_mackerels(curr_x_min, curr_x_max, new_ymin, curr_y_max);
                int b = count_sardines(curr_x_min, curr_x_max, new_ymin, curr_y_max);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = new_ymin;
                    best_new_y_max = curr_y_max;
                    improved = true;
                }
            }

            // Try moving top edge to exclude s
            int new_ymax = ys - 1;
            if (new_ymax >= curr_y_min) {
                int a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, new_ymax);
                int b = count_sardines(curr_x_min, curr_x_max, curr_y_min, new_ymax);
