                }
            }
        }

        if (improved) {
            curr_a = best_new_a;
            curr_b = best_new_b;
            curr_x_min = best_new_x_min;
            curr_x_max = best_new_x_max;
            curr_y_min = best_new_y_min;
            curr_y_max = best_new_y_max;
            curr_val = best_new_val;
        }
    }

    // Expand the rectangle
    while (true) {
        bool expanded = false;

        // Expand left
        int new_xmin_candidate = curr_x_min;
        bool has_mackerel_left = false;
        for (auto m : mackerels) {
            if (m.x < curr_x_min) {
                new_xmin_candidate = min(new_xmin_candidate, m.x);
