using namespace std;

struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;

    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Preprocess sets for mackerels' x and y coordinates
    unordered_set<int> x_mackerels;
    unordered_set<int> y_mackerels;
    for (const auto& p : mackerels) {
        x_mackerels.insert(p.x);
        y_mackerels.insert(p.y);
    }

    // Compute initial rectangle for mackerels
    int x_min1 = INT_MAX;
    int x_max1 = INT_MIN;
    int y_min1 = INT_MAX;
    int y_max1 = INT_MIN;

    for (const auto& p : mackerels) {
        x_min1 = min(x_min1, p.x);
        x_max1 = max(x_max1, p.x);
        y_min1 = min(y_min1, p.y);
        y_max1 = max(y_max1, p.y);
    }

    // Helper functions to count mackerels and sardines in a rectangle
    auto count_mackerels = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        for (const auto& p : mackerels) {
            if (p.x >= x_min && p.x <= x_max && p.y >= y_min && p.y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    auto count_sardines = [&](int x_min, int x_max, int y_min, int y_max) {
        int cnt = 0;
        for (const auto& p : sardines) {
            if (p.x >= x_min && p.x <= x_max && p.y >= y_min && p.y <= y_max) {
                cnt++;
            }
        }
        return cnt;
    };

    int curr_x_min = x_min1;
    int curr_x_max = x_max1;
    int curr_y_min = y_min1;
    int curr_y_max = y_max1;
    int curr_a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
    int curr_b = count_sardines(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
    int curr_val = max(0, curr_a - curr_b + 1);

    bool improved = true;
    while (improved) {
        improved = false;
        vector<Point> current_sardines;
        for (const auto& s : sardines) {
            if (s.x >= curr_x_min && s.x <= curr_x_max && s.y >= curr_y_min && s.y <= curr_y_max) {
                current_sardines.push_back(s);
            }
        }

        if (current_sardines.empty()) {
            break;
        }

        int best_new_val = curr_val;
        int best_new_a = curr_a;
        int best_new_b = curr_b;
        int best_new_x_min = curr_x_min;
        int best_new_x_max = curr_x_max;
        int best_new_y_min = curr_y_min;
        int best_new_y_max = curr_y_max;
        bool found = false;

        for (const auto& s : current_sardines) {
            int xs = s.x;
            int ys = s.y;

            // Option 1: move left edge to xs + 1
            int new_xmin_candidate = xs + 1;
            if (new_xmin_candidate <= curr_x_max) {
                // Check if new_xmin_candidate has any mackerels
                int new_xmin = new_xmin_candidate;
                // Check if there are mackerels with x < new_xmin
                // This is the current x_min, and we are moving it to new_xmin
                // New x_min is new_xmin, and previous x_min was curr_x_min
                // Mackerels with x in [new_xmin, curr_x_max] are included
                // Mackerels with x < new_xmin are excluded
                // To avoid excluding mackerels, we need new_xmin to be the same as the previous x_min
                // But this is not possible
                // So we can't prevent excluding mackerels here
                // Proceed with the check
                int a = count_mackerels(new_xmin_candidate, curr_x_max, curr_y_min, curr_y_max);
                int b = count_sardines(new_xmin_candidate, curr_x_max, curr_y_min, curr_y_max);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = new_xmin_candidate;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = curr_y_max;
                    found = true;
                }
            }

            // Option 2: move right edge to xs - 1
            int new_xmax_candidate = xs - 1;
            if (new_xmax_candidate >= curr_x_min) {
                int a = count_mackerels(curr_x_min, new_xmax_candidate, curr_y_min, curr_y_max);
                int b = count_sardines(curr_x_min, new_xmax_candidate, curr_y_min, curr_y_max);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = new_xmax_candidate;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = curr_y_max;
                    found = true;
                }
            }

            // Option 3: move bottom edge to ys + 1
            int new_ymin_candidate = ys + 1;
            if (new_ymin_candidate <= curr_y_max) {
                int a = count_mackerels(curr_x_min, curr_x_max, new_ymin_candidate, curr_y_max);
                int b = count_sardines(curr_x_min, curr_x_max, new_ymin_candidate, curr_y_max);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = new_ymin_candidate;
                    best_new_y_max = curr_y_max;
                    found = true;
                }
            }

            // Option 4: move top edge to ys - 1
            int new_ymax_candidate = ys - 1;
            if (new_ymax_candidate >= curr_y_min) {
                int a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, new_ymax_candidate);
                int b = count_sardines(curr_x_min, curr_x_max, curr_y_min, new_ymax_candidate);
                int val = a - b;
                if (val > best_new_val) {
                    best_new_val = val;
                    best_new_a = a;
                    best_new_b = b;
                    best_new_x_min = curr_x_min;
                    best_new_x_max = curr_x_max;
                    best_new_y_min = curr_y_min;
                    best_new_y_max = new_ymax_candidate;
                    found = true;
                }
            }
        }

        // After trying to adjust for all sardines, check if any improvement was made
        if (found) {
            curr_val = best_new_val;
            curr_a = best_new_a;
            curr_b = best_new_b;
            curr_x_min = best_new_x_min;
            curr_x_max = best_new_x_max;
            curr_y_min = best_new_y_min;
            curr_y_max = best_new_y_max;
            improved = true;
        }
    }

    // Now try to expand the rectangle in all directions to include more mackerels
    // without introducing new sardines
    while (true) {
        bool expanded = false;

        // Try to expand left
        int new_xmin_candidate = curr_x_min;
        bool has_mackerel_left = false;
        for (const auto& m : mackerels) {
            if (m.x < curr_x_min) {
                new_xmin_candidate = min(new_xmin_candidate, m.x);
                has_mackerel_left = true;
            }
        }
        if (has_mackerel_left) {
            int new_s = count_sardines(new_xmin_candidate, curr_x_max, curr_y_min, curr_y_max);
            if (new_s == curr_b) {
                curr_x_min = new_xmin_candidate;
                curr_a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
                curr_b = new_s;
                expanded = true;
            }
        }

        // Try to expand right
        int new_xmax_candidate = curr_x_max;
        bool has_mackerel_right = false;
        for (const auto& m : mackerels) {
            if (m.x > curr_x_max) {
                new_xmax_candidate = max(new_xmax_candidate, m.x);
                has_mackerel_right = true;
            }
        }
        if (has_mackerel_right) {
            int new_s = count_sardines(curr_x_min, new_xmax_candidate, curr_y_min, curr_y_max);
            if (new_s == curr_b) {
                curr_x_max = new_xmax_candidate;
                curr_a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
                curr_b = new_s;
                expanded = true;
            }
        }

        // Try to expand bottom
        int new_ymin_candidate = curr_y_min;
        bool has_mackerel_bottom = false;
        for (const auto& m : mackerels) {
            if (m.y < curr_y_min) {
                new_ymin_candidate = min(new_ymin_candidate, m.y);
                has_mackerel_bottom = true;
            }
        }
        if (has_mackerel_bottom) {
            int new_s = count_sardines(curr_x_min, curr_x_max, new_ymin_candidate, curr_y_max);
            if (new_s == curr_b) {
                curr_y_min = new_ymin_candidate;
                curr_a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
                curr_b = new_s;
                expanded = true;
            }
        }

        // Try to expand top
        int new_ymax_candidate = curr_y_max;
        bool has_mackerel_top = false;
        for (const auto& m : mackerels) {
            if (m.y > curr_y_max) {
                new_ymax_candidate = max(new_ymax_candidate, m.y);
                has_mackerel_top = true;
            }
        }
        if (has_mackerel_top) {
            int new_s = count_sardines(curr_x_min, curr_x_max, curr_y_min, new_ymax_candidate);
            if (new_s == curr_b) {
                curr_y_max = new_ymax_candidate;
                curr_a = count_mackerels(curr_x_min, curr_x_max, curr_y_min, curr_y_max);
                curr_b = new_s;
                expanded = true;
            }
        }

        if (!expanded) break;
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << curr_x_min << " " << curr_y_min << endl;
    cout << curr_x_max << " " << curr_y_min << endl;
    cout << curr_x_max << " " << curr_y_max << endl;
    cout << curr_x_min << " " << curr_y_max << endl;

    return 0;
}

