        if (best_new_score > current_score) {
            current_score = best_new_score;
            current_x_low = new_x_low;
            current_x_high = new_x_high;
            current_y_low = new_y_low;
            current_y_high = new_y_high;
        } else {
            break;
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << current_x_low << " " << current_y_low << endl;
    cout << current_x_high << " " << current_y_low << endl;
    cout << current_x_high << " " << current_y_high << endl;
    cout << current_x_low << " " << current_y_high << endl;

    return 0;
}
